select count(cve_id) as 'Corrected CVEs last month' from grafana.cves
where last_presence_check > current_date() - interval 1 MONTH
AND last_presence_check != (select last_presence_check from cves ORDER BY last_presence_check desc limit 1);

select AVG(DATEDIFF(last_presence_check, first_appearance)) as 'Days' from grafana.cves
where last_presence_check != (select last_presence_check from cves ORDER BY last_presence_check desc limit 1)
 and first_appearance > current_date() - interval 3 month;

select frequency, count(*) from grafana.campaigns 
where status='enabled'
group by frequency;

select hostname, critical_cves+ high_cves 
from nodes where critical_cves + high_cves > 5 and timestamp = (SELECT MAX(timestamp) FROM nodes)
Union select 'others', SUM( critical_cves + high_cves) 
from nodes 
where critical_cves + high_cves <= 5 and timestamp = (SELECT MAX(timestamp) FROM nodes)
group by others;

